/** Fetch one block, checking connected peers before consulting the DHT. */
public Optional<HashedBlock> getBlock(Want want) {
    Set<PeerId> connected = bitswap.getBroadcastAudience();
    CompletionException firstTimeout = null;
    if (!connected.isEmpty()) {
        try {
            return requestBlock(want, connected);
        } catch (CompletionException failure) {
            if (!(failure.getCause() instanceof TimeoutException))
                throw failure;
            firstTimeout = failure;
        }
    }
    Set<PeerId> providers = dht.findProviders(want.cid, us, 5).join().stream()
            .map(peer -> PeerId.fromBase58(peer.peerId.toBase58()))
            .filter(peer -> !peer.equals(us.getPeerId()) && !connected.contains(peer))
            .collect(Collectors.toSet());
    if (!providers.isEmpty())
        return requestBlock(want, providers);
    if (firstTimeout != null)
        throw firstTimeout;
    return Optional.empty();
}

private Optional<HashedBlock> requestBlock(Want want, Set<PeerId> peers) {
    return bitswap.get(List.of(want), us, peers, false).stream()
            .findFirst().map(CompletableFuture::join);
}

